const updated = { ...user, age: 26 };   // Overwrite age

Object.freeze(obj)     // Make immutable (shallow)
Object.seal(obj)       // Allow modifying, not adding/deleting
Object.isFrozen(obj)
Object.isSealed(obj)

Object.create(proto)   // Create object with given prototype
